SELECT DISTINCT md.chembl_id, md.pref_name, cs.canonical_smiles, di.efo_id AS indication_curie, di.mesh_heading AS indication_label, di.max_phase_for_ind FROM molecule_dictionary md JOIN compound_structures cs ON md.molregno = cs.molregno JOIN drug_indication di ON md.molregno = di.molregno WHERE di.max_phase_for_ind = 4 AND di.mesh_heading = 'HIV Infection' ORDER BY md.chembl_id, md.pref_name, cs.canonical_smiles, di.efo_id, di.mesh_heading, di.max_phase_for_ind
